<script setup>
import { reactive, watch, ref, onMounted, computed } from 'vue'
import { Plus, Trash2, Save, X } from '@lucide/vue'
import { api } from '../api'
import QuizScoringPlan from './QuizScoringPlan.vue'
import LearningRequirementsEditor from './LearningRequirementsEditor.vue'
import {quizScoringPlan} from '../utils/quizScoringPlan'
import { toLocalInput, toUtc } from '../utils/assignments'
const props = defineProps({ initial: { type: Object, default: null }, busy: Boolean, courseId: String, exam: Boolean, quiz: Boolean })
const rubrics = ref([]), rubricError = ref('')
onMounted(async () => { if(props.exam || props.quiz)return; try { rubrics.value = await api(`/courses/${props.courseId || props.initial.courseId}/rubrics`) } catch(e) { rubricError.value = e.message } })
const emit = defineEmits(['save', 'cancel'])
const form = reactive({ title: '', instructions: '', opensAt: '', dueAt: '', questions: [], allowRevisions: false, maxScore: 100, rubricId: null })
const scoring=computed(()=>quizScoringPlan(form.maxScore,form.questions))
watch(() => props.initial, value => {
  Object.assign(form, { learningRequirements: value?.learningGate?.requirements?.map(r=>({resourceId:r.resourceId,minimumSeconds:r.minimumSeconds})) || [], allowRevisions: value?.allowRevisions || false, maxScore: value?.maxScore || 100, rubricId: value?.rubricId || null, title: value?.title || '', instructions: value?.instructions || '', opensAt: toLocalInput(value?.opensAt), dueAt: toLocalInput(value?.dueAt), questions: value?.questions?.map(q => ({ gradingGuidance:q.gradingGuidance||'',points:q.points??null,promptText: q.promptText, stageCode: q.stageCode || '', questionType:q.questionType || 'essay', optionsText:(q.options || []).join('\n'), standardAnswer:q.standardAnswer || [] })) || [{ promptText: '', stageCode: '', questionType:'essay', standardAnswer:[] }] })
}, { immediate: true })
function save() { if(props.quiz && scoring.value.error)return;emit('save', { ...form, opensAt: toUtc(form.opensAt), dueAt: toUtc(form.dueAt), expectedEditVersion: props.initial?.editVersion || null, questions: form.questions.map(q => ({ ...q, gradingGuidance:q.gradingGuidance||'',points:q.points==null||q.points===''?null:Number(q.points), questionType:q.questionType || 'essay', options:q.questionType==='true_false'?['是','非']:(q.optionsText || '').split('\n').filter(x=>x.trim()), standardAnswer:q.questionType && q.questionType!=='essay'?(q.standardAnswer || []):[], stageCode: q.stageCode || null })) }) }
</script>
<template><section class="surface form-surface assignment-editor"><div class="section-title"><div><h2>{{ exam ? '建立考試草稿' : quiz ? (initial?'編輯測驗草稿':'建立線上／課後測驗') : initial ? '編輯作業草稿' : '建立個人作業' }}</h2><p>發布前可以調整題目；發布後題目與說明將鎖定。</p></div><button class="icon-button" type="button" aria-label="關閉作業編輯" :disabled="busy" @click="emit('cancel')"><X :size="18" /></button></div><form @submit.prevent="save"><fieldset :disabled="busy"><label>{{ exam ? "考試名稱" : quiz ? "測驗名稱" : "作業名稱" }}<input v-model="form.title" required maxlength="200" placeholder="例如：案例一 · 個案功能分析" /></label><label class="assignment-field">{{quiz?"測驗說明":"作業說明與案例資料"}}<textarea v-model="form.instructions" rows="5" maxlength="24000" placeholder="說明學習目標、案例內容與作答要求。"></textarea></label><div class="form-grid assignment-field"><label>開放作答時間（選填）<input v-model="form.opensAt" type="datetime-local" /></label><label>截止時間（選填）<input v-model="form.dueAt" type="datetime-local" :min="form.opensAt || undefined" /></label></div><p class="field-hint">時間依你的裝置時區顯示；未設定截止時間時，可作答至教師關閉作業。</p><template v-if="!exam"><p v-if="rubricError" class="error-box" role="alert">{{ rubricError }}</p><div class="form-grid"><label>{{quiz?"測驗滿分":"作業滿分"}}<input v-model.number="form.maxScore" type="number" min="0.01" max="999999" step="0.01" required /></label><label v-if="!quiz">評分規準<select v-model="form.rubricId" aria-label="評分規準"><option :value="null">不使用規準，直接評分</option><option v-for="r in rubrics" :key="r.id" :value="r.id">{{ r.title }} · v{{ r.versionNo }}</option></select></label></div><label v-if="!quiz" class="assignment-field"><input v-model="form.allowRevisions" type="checkbox" />允許學生在截止前提交修訂版本</label><p v-if="!quiz" class="field-hint">發布後政策鎖定；每次提交保留完整快照，新版本需重新評分。</p></template><LearningRequirementsEditor v-if="quiz" v-model="form.learningRequirements" :course-id="courseId || initial?.courseId" /><QuizScoringPlan v-if="quiz" :max-score="form.maxScore" :questions="form.questions" /><div class="section-title"><h3>{{quiz?"測驗題目":"作業題目"}} <span class="count-pill">{{ form.questions.length }}</span></h3></div><div v-for="(question, index) in form.questions" :key="index" class="question-editor"><div class="question-editor-header"><strong>題目 {{ index + 1 }}</strong><label>題型<select aria-label="題型" v-model="question.questionType" @change="question.standardAnswer=[]"><option value="essay">申論題</option><option value="true_false">是非題</option><option value="single">單選題</option><option value="multiple">多選題</option></select></label><label v-if="quiz">配分（留白自動均分）<input :aria-label="`題目 ${index+1} 配分`" v-model="question.points" type="number" min="0.01" step="0.01" /></label><button type="button" class="icon-button" :aria-label="`移除題目 ${index + 1}`" :disabled="form.questions.length === 1" @click="form.questions.splice(index, 1)"><Trash2 :size="16" /></button></div><label :for="`question-prompt-${index}`" class="sr-only">題目 {{ index + 1 }} 內容</label><textarea :id="`question-prompt-${index}`" v-model="question.promptText" required maxlength="8000" rows="3" placeholder="輸入題目內容…"></textarea><label v-if="quiz && (question.questionType||'essay')==='essay'">教師評分參考（學生不可見）<textarea v-model="question.gradingGuidance" maxlength="8000" rows="5" placeholder="例如：36–40 分的判斷條件、各分析面向配分。"></textarea></label><template v-if="question.questionType && question.questionType !== 'essay'"><label v-if="question.questionType !== 'true_false'">選項（每行一個）<textarea v-model="question.optionsText" rows="4" @input="question.standardAnswer=[]"></textarea></label><fieldset><legend>標準答案（僅教師／助教可見）</legend><label class="choice-label" v-for="(option, n) in (question.questionType==='true_false'?['是','非']:(question.optionsText || '').split('\n').filter(x=>x.trim()))" :key="n"><input type="checkbox" :checked="question.standardAnswer?.includes(n)" @change="question.standardAnswer=question.questionType==='multiple'?($event.target.checked?[...(question.standardAnswer || []),n]:(question.standardAnswer || []).filter(x=>x!==n)):($event.target.checked?[n]:[])" />{{ option }}</label></fieldset></template></div><button type="button" class="button secondary" :disabled="form.questions.length >= 20" @click="form.questions.push({ promptText: '', stageCode: '', questionType:'essay', standardAnswer:[] })"><Plus :size="16" />新增題目</button><div class="form-bottom"><p class="field-hint">{{quiz?"客觀題自動批改 · 多選全對得分 · 申論題人工評分 · 發布後納入平均":"個人作業 · 每位學生一份作答 · 本階段不自動評分"}}</p><button type="submit" class="button primary" :disabled="busy || (quiz && !!scoring.error)"><Save :size="16" />{{ busy ? '儲存中…' : exam ? '儲存考試草稿' : quiz ? '儲存測驗草稿' : '儲存作業草稿' }}</button></div></fieldset></form></section></template>
